    "title": "Integrating a tailored recurrent neural network with Bayesian experimental design to optimize microbial community functions",
    "titleZh": "设计、实验、学习三阶段围绕反馈闭环，局部小图解释模块输出。",
    "summary": "The Microbiome Recurrent Neural Network (MiRNN) learns system dynamics and proposes new designs.\n(Design) An experimental design space, denoted as Q, is a set of individual experimental conditions, q, where a particular condition could, for example, be a set of species in a community or the initial concentrations of resources. MiRNN predictions of outcomes for a set of experimental conditions, q, are evaluated by an acquisition function, f, which balances the expected information gain (EIG) of an experimental design and its expected profit to evaluate the optimality of experimental designs. (Test) The optimal experimental design, q*, defines a set of experimental conditions to be observed experimentally. Measurements of these conditions are collected in the test phase. (Learn) Data collected in the test phase, and all previously collected data, are used to fit an updated MiRNN model. Once fit to the newly acquired data, the updated MiRNN model can be used again in the design phase to complete the design, test, learn cycle.",
    "originalCaption": "The Microbiome Recurrent Neural Network (MiRNN) learns system dynamics and proposes new designs.\n(Design) An experimental design space, denoted as Q, is a set of individual experimental conditions, q, where a particular condition could, for example, be a set of species in a community or the initial concentrations of resources. MiRNN predictions of outcomes for a set of experimental conditions, q, are evaluated by an acquisition function, f, which balances the expected information gain (EIG) of an experimental design and its expected profit to evaluate the optimality of experimental designs. (Test) The optimal experimental design, q*, defines a set of experimental conditions to be observed experimentally. Measurements of these conditions are collected in the test phase. (Learn) Data collected in the test phase, and all previously collected data, are used to fit an updated MiRNN model. Once fit to the newly acquired data, the updated MiRNN model can be used again in the design phase to complete the design, test, learn cycle.",
    "shortIntroZh": "设计、实验、学习三阶段围绕反馈闭环，局部小图解释模块输出。",
    "detailZh": "设计、实验、学习三阶段围绕反馈闭环，局部小图解释模块输出。 外观中的曲面和阴影不能覆盖图研SVG静态渲染限制。",
