      "captionEvidence": "<fig xmlns:ns0=\"http://www.w3.org/1999/xlink\" xmlns:ns1=\"http://www.w3.org/1998/Math/MathML\" id=\"pcbi.1011436.g001\" position=\"float\">\n<object-id pub-id-type=\"doi\">10.1371/journal.pcbi.1011436.g001</object-id>\n<label>Fig 1</label>\n<caption>\n<title>The Microbiome Recurrent Neural Network (MiRNN) learns system dynamics and proposes new designs.</title>\n<p>(<bold>Design</bold>) An experimental design space, denoted as <inline-formula id=\"pcbi.1011436.e003\"><alternatives><graphic id=\"pcbi.1011436.e003g\" mimetype=\"image\" position=\"anchor\" ns0:href=\"info:doi/10.1371/journal.pcbi.1011436.e003\" ns0:type=\"simple\" /><ns1:math display=\"inline\" id=\"M3\"><ns1:mi mathvariant=\"script\">Q</ns1:mi></ns1:math></alternatives></inline-formula>, is a set of individual experimental conditions, <bold>q</bold>, where a particular condition could, for example, be a set of species in a community or the initial concentrations of resources. MiRNN predictions of outcomes for a set of experimental conditions, <bold>q</bold>, are evaluated by an acquisition function, <italic>f</italic>, which balances the expected information gain (EIG) of an experimental design and its expected profit to evaluate the optimality of experimental designs. (<bold>Test</bold>) The optimal experimental design, <bold>q</bold>*, defines a set of experimental conditions to be observed experimentally. Measurements of these conditions are collected in the test phase. (<bold>Learn</bold>) Data collected in the test phase, and all previously collected data, are used to fit an updated MiRNN model. Once fit to the newly acquired data, the updated MiRNN model can be used again in the design phase to complete the design, test, learn cycle.</p>\n</caption>\n<graphic mimetype=\"image\" position=\"float\" ns0:href=\"info:doi/10.1371/journal.pcbi.1011436.g001\" ns0:type=\"simple\" />\n</fig>\n",
