    "title": "Integrating a tailored recurrent neural network with Bayesian experimental design to optimize microbial community functions",
    "titleZh": "时间展开结构与单元展开结构分开，保留张量符号。",
    "summary": "Microbiome Recurrent Neural Network architecture.\nInputs to the RNN at time step t − 1 include the state of species abundances, metabolite concentrations, control inputs, and a latent vector that stores information from previous steps and whose dimension determines the flexibility of the model. The output from each MiRNN block is the predicted system state and the latent vector at the next time step, t. To avoid the physically unrealistic emergence of previously absent species, a constrained feed-forward neural network (FFNN) outputs zero valued species abundances if species abundances at the previous time step were zero.",
    "originalCaption": "Microbiome Recurrent Neural Network architecture.\nInputs to the RNN at time step t − 1 include the state of species abundances, metabolite concentrations, control inputs, and a latent vector that stores information from previous steps and whose dimension determines the flexibility of the model. The output from each MiRNN block is the predicted system state and the latent vector at the next time step, t. To avoid the physically unrealistic emergence of previously absent species, a constrained feed-forward neural network (FFNN) outputs zero valued species abundances if species abundances at the previous time step were zero.",
    "shortIntroZh": "时间展开结构与单元展开结构分开，保留张量符号。",
    "detailZh": "时间展开结构与单元展开结构分开，保留张量符号。 保持新模型的尺寸和约束；不能凭参考图添加网络层。",
