    "title": "scSDNE: A semi-supervised method for inferring cell-cell interactions based on graph embedding",
    "titleZh": "集合交集与模型识别性能分开，面板保持单一表达职责。",
    "summary": "Comparison of the performance of scSDNE with CellChat, CellPhoneDB, iTALK and scTenifoldXct on the scRNA-seq dataset of gastric cancer (from fibroblasts to macrophages).(A) Circos plot depicts the strength of intercellular communication from fibroblasts to other cell types in TME. (B) UpSetR plot illustrates the results from the five tools utilizing their respective LR database. The horizontal bar graph in the lower left corner represents the total number of L-R pairs detected by each method. The intercellular communication results obtained by the different methods are represented by multiple black dots and connecting lines, and the number of intersections displayed in the bar graph above. (C) UpSetR plot shows the results from the five tools using a common LRdb. (D) ROC curves plot depicts the performance of the five methods in assessing intercellular communication. (E) Overlap analysis of the LR database. (F) Comparison of literature support rates for scSDNE using different databases.",
    "originalCaption": "Comparison of the performance of scSDNE with CellChat, CellPhoneDB, iTALK and scTenifoldXct on the scRNA-seq dataset of gastric cancer (from fibroblasts to macrophages).(A) Circos plot depicts the strength of intercellular communication from fibroblasts to other cell types in TME. (B) UpSetR plot illustrates the results from the five tools utilizing their respective LR database. The horizontal bar graph in the lower left corner represents the total number of L-R pairs detected by each method. The intercellular communication results obtained by the different methods are represented by multiple black dots and connecting lines, and the number of intersections displayed in the bar graph above. (C) UpSetR plot shows the results from the five tools using a common LRdb. (D) ROC curves plot depicts the performance of the five methods in assessing intercellular communication. (E) Overlap analysis of the LR database. (F) Comparison of literature support rates for scSDNE using different databases.",
