    "title": "Automated visualization of rule-based models",
    "titleZh": "用实体、状态与规则图对应文字模型。",
    "summary": "Visualizing rules of an enzyme-substrate system.\n(A) Structured molecule types Enz and Sub, their respective components (enclosed in ‘()’) and their available internal states (prefixed by ~), shown in BioNetGen syntax and graphic. (B) Reaction rules specifying the adding and removing of an enzyme-substrate bond (binding partners tagged by !1) and phosphorylation of components p1 and p2, shown in BioNetGen syntax. The reactants and products of a reaction rule are called patterns. (C) Conventional rule visualization by drawing reactant and product patterns separately. (D) Compact rule visualization displays operations (purple nodes) that transform the reactant patterns in each rule. On operation nodes, outward edges indicate that a new structure is produced (bond in R1, state pY in R2 and R3) and inward edges indicate that a structure is consumed (bond in _reverse_R1, state Y in R2 and R3). To see operation nodes with their labels, see S1 Fig.",
    "originalCaption": "Visualizing rules of an enzyme-substrate system.\n(A) Structured molecule types Enz and Sub, their respective components (enclosed in ‘()’) and their available internal states (prefixed by ~), shown in BioNetGen syntax and graphic. (B) Reaction rules specifying the adding and removing of an enzyme-substrate bond (binding partners tagged by !1) and phosphorylation of components p1 and p2, shown in BioNetGen syntax. The reactants and products of a reaction rule are called patterns. (C) Conventional rule visualization by drawing reactant and product patterns separately. (D) Compact rule visualization displays operations (purple nodes) that transform the reactant patterns in each rule. On operation nodes, outward edges indicate that a new structure is produced (bond in R1, state pY in R2 and R3) and inward edges indicate that a structure is consumed (bond in _reverse_R1, state Y in R2 and R3). To see operation nodes with their labels, see S1 Fig.",
    "shortIntroZh": "用实体、状态与规则图对应文字模型。",
    "detailZh": "用实体、状态与规则图对应文字模型。 酶底物和磷酸化位点来自此论文，不应复制到其他机制。",
