      "evidenceFile": "docs/infographic-v400/evidence/papers/pcbi.1005857.xml",
      "captionEvidence": "<fig xmlns:ns0=\"http://www.w3.org/1999/xlink\" id=\"pcbi.1005857.g002\" position=\"float\">\n<object-id pub-id-type=\"doi\">10.1371/journal.pcbi.1005857.g002</object-id>\n<label>Fig 2</label>\n<caption>\n<title>Visualizing rules of an enzyme-substrate system.</title>\n<p>(A) Structured molecule types Enz and Sub, their respective components (enclosed in ‘()’) and their available internal states (prefixed by ~), shown in BioNetGen syntax and graphic. (B) Reaction rules specifying the adding and removing of an enzyme-substrate bond (binding partners tagged by !1) and phosphorylation of components <italic>p1</italic> and <italic>p2</italic>, shown in BioNetGen syntax. The reactants and products of a reaction rule are called patterns. (C) Conventional rule visualization by drawing reactant and product patterns separately. (D) Compact rule visualization displays operations (purple nodes) that transform the reactant patterns in each rule. On operation nodes, outward edges indicate that a new structure is produced (bond in R1, state <italic>pY</italic> in R2 and R3) and inward edges indicate that a structure is consumed (bond in _reverse_R1, state <italic>Y</italic> in R2 and R3). To see operation nodes with their labels, see <xref ref-type=\"supplementary-material\" rid=\"pcbi.1005857.s001\">S1 Fig</xref>.</p>\n</caption>\n<graphic mimetype=\"image\" position=\"float\" ns0:href=\"info:doi/10.1371/journal.pcbi.1005857.g002\" ns0:type=\"simple\" />\n</fig>\n",
