    "titleZh": "正反馈和抑制模式分面表达，调控符号保留区别。",
    "summary": "Signaling motifs in the FcεRI library recovered from the compressed AR graph.\n(A) Positive feedback loops enhance binding of Src family kinases Lyn and Fyn (denoted SFK) to receptor and Pag1 scaffold as well as Syk auto-phosphorylation. (B) Pag1 phosphorylated by SFKs recruits Csk, which negatively regulates SFKs by phosphorylation. (C) A coherent feed-forward loop activates Plcg1 from phosphorylated Lat. (D) An incoherent feed-forward loop involving enzymes PI3K and Inpp5d (a.k.a. SHP2) regulates levels of phosphoinositide PIP3, which is phosphorylated at both 3’ and 5’ hydroxyl positions (denoted PI_3P and PI_5P respectively).",
    "originalCaption": "Signaling motifs in the FcεRI library recovered from the compressed AR graph.\n(A) Positive feedback loops enhance binding of Src family kinases Lyn and Fyn (denoted SFK) to receptor and Pag1 scaffold as well as Syk auto-phosphorylation. (B) Pag1 phosphorylated by SFKs recruits Csk, which negatively regulates SFKs by phosphorylation. (C) A coherent feed-forward loop activates Plcg1 from phosphorylated Lat. (D) An incoherent feed-forward loop involving enzymes PI3K and Inpp5d (a.k.a. SHP2) regulates levels of phosphoinositide PIP3, which is phosphorylated at both 3’ and 5’ hydroxyl positions (denoted PI_3P and PI_5P respectively).",
