    "title": "Automated visualization of rule-based models",
    "titleZh": "同一规则系统以不同语言表达，验证图型相似但语义不等价。",
    "summary": "Other visualization approaches applied to the enzyme-substrate phosphorylation model of Fig 2.\n(A) The binding rule drawn using SBGN Process Description conventions, which require visual graph comparison. (B) Kappa story, showing the causal order of rules that produces sub_pp, which refers to doubly phosphorylated substrate. (C) Simmune Network Viewer diagram, which merges patterns across rules and hides certain causal dependencies (details in S4 Fig). Here, the Enz.Sub node merges all enzyme-substrate patterns shown in Fig 2. (D) SBGN Entity Relationship. (E) Molecular Interaction Map. Panels D-E require manual interpretation of the model, like the extended contact map. (F) rxncon regulatory graph visualization of the rxncon model format, which can only depict a limited subset of reaction rules (details in S5 Fig).",
    "originalCaption": "Other visualization approaches applied to the enzyme-substrate phosphorylation model of Fig 2.\n(A) The binding rule drawn using SBGN Process Description conventions, which require visual graph comparison. (B) Kappa story, showing the causal order of rules that produces sub_pp, which refers to doubly phosphorylated substrate. (C) Simmune Network Viewer diagram, which merges patterns across rules and hides certain causal dependencies (details in S4 Fig). Here, the Enz.Sub node merges all enzyme-substrate patterns shown in Fig 2. (D) SBGN Entity Relationship. (E) Molecular Interaction Map. Panels D-E require manual interpretation of the model, like the extended contact map. (F) rxncon regulatory graph visualization of the rxncon model format, which can only depict a limited subset of reaction rules (details in S5 Fig).",
    "shortIntroZh": "同一规则系统以不同语言表达，验证图型相似但语义不等价。",
    "detailZh": "同一规则系统以不同语言表达，验证图型相似但语义不等价。 SBGN PD、ER、Kappa和rxncon不可互相替代；F不标为SBGN AF。",
