      "captionEvidence": "<fig xmlns:ns0=\"http://www.w3.org/1999/xlink\" id=\"pcbi.1005857.g011\" position=\"float\">\n<object-id pub-id-type=\"doi\">10.1371/journal.pcbi.1005857.g011</object-id>\n<label>Fig 11</label>\n<caption>\n<title>Other visualization approaches applied to the enzyme-substrate phosphorylation model of <xref ref-type=\"fig\" rid=\"pcbi.1005857.g002\">Fig 2</xref>.</title>\n<p>(A) The binding rule drawn using SBGN Process Description conventions, which require visual graph comparison. (B) Kappa story, showing the causal order of rules that produces sub_pp, which refers to doubly phosphorylated substrate. (C) Simmune Network Viewer diagram, which merges patterns across rules and hides certain causal dependencies (details in <xref ref-type=\"supplementary-material\" rid=\"pcbi.1005857.s004\">S4 Fig</xref>). Here, the Enz.Sub node merges all enzyme-substrate patterns shown in <xref ref-type=\"fig\" rid=\"pcbi.1005857.g002\">Fig 2</xref>. (D) SBGN Entity Relationship. (E) Molecular Interaction Map. Panels D-E require manual interpretation of the model, like the extended contact map. (F) <italic>rxncon</italic> regulatory graph visualization of the <italic>rxncon</italic> model format, which can only depict a limited subset of reaction rules (details in <xref ref-type=\"supplementary-material\" rid=\"pcbi.1005857.s005\">S5 Fig</xref>).</p>\n</caption>\n<graphic mimetype=\"image\" position=\"float\" ns0:href=\"info:doi/10.1371/journal.pcbi.1005857.g011\" ns0:type=\"simple\" />\n</fig>\n",
