    "titleZh": "并列连接模式暴露一对一、全连接、固定度等定义差别。",
    "summary": "Connectivity patterns reflecting the most common rules.\nThe ordered set of sources S is depicted by the green squares on the left. They are connected to the ordered set of targets T, depicted by the orange squares on the right. The respective in- and out-degrees are given next to the nodes. (A) One-to-one. (B) All-to-all. (C) Random, fixed in-degree with K_{in} connections per target node. (D) Random, fixed out-degree with K_{out} connections per source node. (E) Random, fixed total number of connections N_{syn}. (F) Pairwise Bernoulli with connection probability p. (G) Autapse (self-connection). (H) Multapse (multi-connection).",
    "originalCaption": "Connectivity patterns reflecting the most common rules.\nThe ordered set of sources S is depicted by the green squares on the left. They are connected to the ordered set of targets T, depicted by the orange squares on the right. The respective in- and out-degrees are given next to the nodes. (A) One-to-one. (B) All-to-all. (C) Random, fixed in-degree with K_{in} connections per target node. (D) Random, fixed out-degree with K_{out} connections per source node. (E) Random, fixed total number of connections N_{syn}. (F) Pairwise Bernoulli with connection probability p. (G) Autapse (self-connection). (H) Multapse (multi-connection).",
    "shortIntroZh": "并列连接模式暴露一对一、全连接、固定度等定义差别。",
