    "title": "Data analysis and modeling pipelines for controlled networked social science experiments",
    "titleZh": "保持相同框架位置，并列展示管线配置差异。",
    "summary": "Two pipelines are shown to illustrate similarities and differences between them.\nTo run a pipeline (called a job), a pipeline-specific configuration input file is verified and is read by the pipeline framework. The file specifies h-functions and their order of execution, as well as required input files to the pipeline. Here we show how function h_{1} is executed in a pipeline 1 and how h_{4} is executed in pipeline 2. The pipeline framework invokes the corresponding functions. If specified in the configuration file, the pipeline framework invokes a transformation function that transforms the contents of one or more files into an input file of correct format for the h-function. There may be one transformation function for each direct input to an h-function. At appropriate points in a pipeline, data files are verified against their corresponding JSON schema (input file verification). The h-function is executed and output files are generated (these digital object outputs may be, e.g., plot files, ASCII data files, and binary data files). There may be additional h-functions within pipeline 1, indicated by the ellipsis below pipeline 1 function h_{1} execution. In this example, outputs from the generic pipeline 1 are inputs for the generic pipeline 2. Function h_{4} in pipeline 2 is executed in a similar fashion to function h_{1} in pipeline 1. See the text for descriptions of these various components. Note: the pipeline framework (in brown) is the same code for all pipelines. See Table 5 for implementation details of the elements in this figure.",
    "originalCaption": "Two pipelines are shown to illustrate similarities and differences between them.\nTo run a pipeline (called a job), a pipeline-specific configuration input file is verified and is read by the pipeline framework. The file specifies h-functions and their order of execution, as well as required input files to the pipeline. Here we show how function h_{1} is executed in a pipeline 1 and how h_{4} is executed in pipeline 2. The pipeline framework invokes the corresponding functions. If specified in the configuration file, the pipeline framework invokes a transformation function that transforms the contents of one or more files into an input file of correct format for the h-function. There may be one transformation function for each direct input to an h-function. At appropriate points in a pipeline, data files are verified against their corresponding JSON schema (input file verification). The h-function is executed and output files are generated (these digital object outputs may be, e.g., plot files, ASCII data files, and binary data files). There may be additional h-functions within pipeline 1, indicated by the ellipsis below pipeline 1 function h_{1} execution. In this example, outputs from the generic pipeline 1 are inputs for the generic pipeline 2. Function h_{4} in pipeline 2 is executed in a similar fashion to function h_{1} in pipeline 1. See the text for descriptions of these various components. Note: the pipeline framework (in brown) is the same code for all pipelines. See Table 5 for implementation details of the elements in this figure.",
