    "summary": "Co-occurrence network among the first 100 genera of fungi (a) and bacteria (b). The correlation matrix is constructed using the SparCC algorithm, but ASVs with a total number of sequences less than 10 are filtered based on random matrix theory (RMT) before matrix construction, with thresholds of 0.33 (fungi) and 0.6 (bacteria) (Chi-Square, p≤0.05). The top 100 ASVs were extracted to construct a network by the induced_subgraph function of igraph R package. The deeper and thicker lines represent stronger correlations between genera.",
    "originalCaption": "Co-occurrence network among the first 100 genera of fungi (a) and bacteria (b). The correlation matrix is constructed using the SparCC algorithm, but ASVs with a total number of sequences less than 10 are filtered based on random matrix theory (RMT) before matrix construction, with thresholds of 0.33 (fungi) and 0.6 (bacteria) (Chi-Square, p≤0.05). The top 100 ASVs were extracted to construct a network by the induced_subgraph function of igraph R package. The deeper and thicker lines represent stronger correlations between genera.",
