    "summary": "Synteny plot surrounding the Telomerase RNA (TR) gene.Each panel is showing a focal species (A) M. aurantiacus ssp. puniceus, (B) M. guttatus, and (C) M. verbenaceus, and its TR chromosomal location (indicated with a red arrow) is plotted in the central position and highlighted with red letters. Orange arrows indicate genes and gray boxes indicate orthology between genes. For each focal species TR gene, we show the five genes upstream and downstream with an orthology. In each plot there is clear synteny between species surrounding a focal species TR gene, but in the non-focal species there is no TR gene and instead it is located at a different chromosome (compare the TR locations in panel A, B, and C).",
    "originalCaption": "Synteny plot surrounding the Telomerase RNA (TR) gene.Each panel is showing a focal species (A) M. aurantiacus ssp. puniceus, (B) M. guttatus, and (C) M. verbenaceus, and its TR chromosomal location (indicated with a red arrow) is plotted in the central position and highlighted with red letters. Orange arrows indicate genes and gray boxes indicate orthology between genes. For each focal species TR gene, we show the five genes upstream and downstream with an orthology. In each plot there is clear synteny between species surrounding a focal species TR gene, but in the non-focal species there is no TR gene and instead it is located at a different chromosome (compare the TR locations in panel A, B, and C).",
