    "title": "Long transposon-rich centromeres in an oomycete reveal divergence of centromere features in Stramenopila-Alveolata-Rhizaria lineages",
    "titleZh": "矩形与环形布局展示拓扑，枝长和节点支持度明确。",
    "summary": "Phylogenetic analyses of CoLT.\n(A) Maximum-likelihood phylogeny of different retroelements. Protein sequences of the reverse transcriptase (RT) domains were used to construct the tree [87] (see S4A File for the complete DNA and protein sequences). The tree was rooted in the midpoint and branch support values (> 50%) shown at the three nodes were determined by 10,000 replicates of both ultrafast bootstrap approximation (UFBoot) and the Shimodaira-Hasegawa approximate likelihood ratio test (SH-aLRT). (B) Maximum-likelihood phylogeny of full-length CoLT elements identified in the Psojae2010.1 genome assembly. CoLT copies located inside and outside of centromeres are denoted by blue and red circles. CoLT elements with full-length coding sequences (CDS) are depicted as filled circles. A CoLT sequence identified in P. citricola served as an outgroup. See S4B File for the CoLT copies used for the phylogenetic analysis.",
    "originalCaption": "Phylogenetic analyses of CoLT.\n(A) Maximum-likelihood phylogeny of different retroelements. Protein sequences of the reverse transcriptase (RT) domains were used to construct the tree [87] (see S4A File for the complete DNA and protein sequences). The tree was rooted in the midpoint and branch support values (> 50%) shown at the three nodes were determined by 10,000 replicates of both ultrafast bootstrap approximation (UFBoot) and the Shimodaira-Hasegawa approximate likelihood ratio test (SH-aLRT). (B) Maximum-likelihood phylogeny of full-length CoLT elements identified in the Psojae2010.1 genome assembly. CoLT copies located inside and outside of centromeres are denoted by blue and red circles. CoLT elements with full-length coding sequences (CDS) are depicted as filled circles. A CoLT sequence identified in P. citricola served as an outgroup. See S4B File for the CoLT copies used for the phylogenetic analysis.",
    "shortIntroZh": "矩形与环形布局展示拓扑，枝长和节点支持度明确。",
    "detailZh": "矩形与环形布局展示拓扑，枝长和节点支持度明确。 布局只是变体；中点定根和外群定根有不同科学前提。",
