      "captionEvidence": "<fig xmlns:ns0=\"http://www.w3.org/1999/xlink\" id=\"pgen.1008646.g006\" position=\"float\">\n<object-id pub-id-type=\"doi\">10.1371/journal.pgen.1008646.g006</object-id>\n<label>Fig 6</label>\n<caption>\n<title>Phylogenetic analyses of CoLT.</title>\n<p>(A) Maximum-likelihood phylogeny of different retroelements. Protein sequences of the reverse transcriptase (RT) domains were used to construct the tree [<xref ref-type=\"bibr\" rid=\"pgen.1008646.ref087\">87</xref>] (see <xref ref-type=\"supplementary-material\" rid=\"pgen.1008646.s022\">S4A File</xref> for the complete DNA and protein sequences). The tree was rooted in the midpoint and branch support values (&gt; 50%) shown at the three nodes were determined by 10,000 replicates of both ultrafast bootstrap approximation (UFBoot) and the Shimodaira-Hasegawa approximate likelihood ratio test (SH-aLRT). (B) Maximum-likelihood phylogeny of full-length CoLT elements identified in the Psojae2010.1 genome assembly. CoLT copies located inside and outside of centromeres are denoted by blue and red circles. CoLT elements with full-length coding sequences (CDS) are depicted as filled circles. A CoLT sequence identified in <italic>P</italic>. <italic>citricola</italic> served as an outgroup. See <xref ref-type=\"supplementary-material\" rid=\"pgen.1008646.s022\">S4B File</xref> for the CoLT copies used for the phylogenetic analysis.</p>\n</caption>\n<graphic mimetype=\"image\" position=\"float\" ns0:href=\"info:doi/10.1371/journal.pgen.1008646.g006\" ns0:type=\"simple\" />\n</fig>\n",
