    "title": "Trade-off between local transmission and long-range dispersal drives infectious disease outbreak size in spatially structured populations",
    "titleZh": "不同传输核函数用线色区分，坐标单位明确。",
    "summary": "Transmission kernels.\nThe parameter h_{0} has been rescaled such that R_{0}, for an homogenous configuration, is the same for all the three kernels. Specifically, R_{0} is 1.9 for all three kernels; α = 1.5 and h_{0} = 0.001 for the fat-tailed kernel; α = 2,1 and h_{0} = 0.005 for the default kernel; α = 4 and h_{0} = 0.026 for the default kernel. Parameter values are based on estimates by Boender et al. [5] for the Dutch epidemic of avian influenza in 2003, but with rescaling to account for the decrease in number of farms (from 5,360 to 2,157) and concomitant increase in size of farms since 2003.",
    "originalCaption": "Transmission kernels.\nThe parameter h_{0} has been rescaled such that R_{0}, for an homogenous configuration, is the same for all the three kernels. Specifically, R_{0} is 1.9 for all three kernels; α = 1.5 and h_{0} = 0.001 for the fat-tailed kernel; α = 2,1 and h_{0} = 0.005 for the default kernel; α = 4 and h_{0} = 0.026 for the default kernel. Parameter values are based on estimates by Boender et al. [5] for the Dutch epidemic of avian influenza in 2003, but with rescaling to account for the decrease in number of farms (from 5,360 to 2,157) and concomitant increase in size of farms since 2003.",
