    "panelTypes": [],
    "title": "Mathematical modeling reveals ferritin as the strongest cellular driver of dietary iron transfer block in enterocytes",
    "titleZh": "区室、实体池和过程节点按SBGN明确组织，转运方向可追踪。",
    "summary": "Enterocyte iron absorption model, SBGN process diagram.A model encapsulating iron transport from the intestinal lumen through a single enterocyte was constructed using COPASI [24–26]. Species inclusion is motivated by the intent to capture a minimal, but sufficient detail needed to reproduce the mucosal block phenomenon in duodenal enterocytes. The model has 5 compartments (lumen, cytoplasm, and blood, which are three-dimensional, and the apical and basal membranes, which are two-dimensional). Thirteen model variables are included to track the concentrations and densities of the relevant chemical species. Abbreviations: DMT1: divalent metal transporter 1, FT: ferritin, DFP: diferric peroxo complex ferric intermediate (ferric iron in FT), core: FT mineralized core iron, IRPs: iron regulatory proteins, FPN: ferroportin, LIP: labile iron pool, Fe: iron (lumen, blood, and body forms). Figure created with Cell Designer [99] and Inkscape, adopting the Systems Biology Graphical Notation standard (SBGN) [100,101].",
    "originalCaption": "Enterocyte iron absorption model, SBGN process diagram.A model encapsulating iron transport from the intestinal lumen through a single enterocyte was constructed using COPASI [24–26]. Species inclusion is motivated by the intent to capture a minimal, but sufficient detail needed to reproduce the mucosal block phenomenon in duodenal enterocytes. The model has 5 compartments (lumen, cytoplasm, and blood, which are three-dimensional, and the apical and basal membranes, which are two-dimensional). Thirteen model variables are included to track the concentrations and densities of the relevant chemical species. Abbreviations: DMT1: divalent metal transporter 1, FT: ferritin, DFP: diferric peroxo complex ferric intermediate (ferric iron in FT), core: FT mineralized core iron, IRPs: iron regulatory proteins, FPN: ferroportin, LIP: labile iron pool, Fe: iron (lumen, blood, and body forms). Figure created with Cell Designer [99] and Inkscape, adopting the Systems Biology Graphical Notation standard (SBGN) [100,101].",
    "shortIntroZh": "区室、实体池和过程节点按SBGN明确组织，转运方向可追踪。",
    "detailZh": "区室、实体池和过程节点按SBGN明确组织，转运方向可追踪。 必须保留专业记号语义；普通美化不能删除过程节点。",
