      "verifiedAt": "2026-10-10",
      "basis": "2025\nMasison, Mendes\n\nThis is an open access article distributed under the terms of the Creative Commons Attribution License, which permits unrestricted use, distribution, and reproduction in any medium, provided the original author and source are credited.",
      "evidenceFile": "docs/infographic-v400/evidence/papers/pcbi.1012374.xml",
      "captionEvidence": "<fig xmlns:ns0=\"http://www.w3.org/1999/xlink\" id=\"pcbi.1012374.g001\" position=\"float\"><object-id pub-id-type=\"doi\">10.1371/journal.pcbi.1012374.g001</object-id><label>Fig 1</label><caption><title>Enterocyte iron absorption model, SBGN process diagram.</title><p>A model encapsulating iron transport from the intestinal lumen through a single enterocyte was constructed using COPASI [<xref ref-type=\"bibr\" rid=\"pcbi.1012374.ref024\">24</xref>–<xref ref-type=\"bibr\" rid=\"pcbi.1012374.ref026\">26</xref>]. Species inclusion is motivated by the intent to capture a minimal, but sufficient detail needed to reproduce the mucosal block phenomenon in duodenal enterocytes. The model has 5 compartments (lumen, cytoplasm, and blood, which are three-dimensional, and the apical and basal membranes, which are two-dimensional). Thirteen model variables are included to track the concentrations and densities of the relevant chemical species. Abbreviations: DMT1: divalent metal transporter 1, FT: ferritin, DFP: diferric peroxo complex ferric intermediate (ferric iron in FT), core: FT mineralized core iron, IRPs: iron regulatory proteins, FPN: ferroportin, LIP: labile iron pool, Fe: iron (lumen, blood, and body forms). Figure created with Cell Designer [<xref ref-type=\"bibr\" rid=\"pcbi.1012374.ref099\">99</xref>] and Inkscape, adopting the Systems Biology Graphical Notation standard (SBGN) [<xref ref-type=\"bibr\" rid=\"pcbi.1012374.ref100\">100</xref>,<xref ref-type=\"bibr\" rid=\"pcbi.1012374.ref101\">101</xref>].</p></caption>\n<graphic mimetype=\"image\" position=\"float\" ns0:href=\"info:doi/10.1371/journal.pcbi.1012374.g001\" ns0:type=\"simple\" /></fig>\n",
