    "title": "Stratigraphic architecture of the Belly River Group (Campanian, Cretaceous) in the plains of southern Alberta: Revisions and updates to an existing model and implications for correlating dinosaur-rich strata",
    "titleZh": "顶部剖面路线与底部测井位置对齐，色带表达地层连续性并显示标高。",
    "summary": "Stratigraphic cross-section A–A’.\nCross-section A-A’ is based on data from 35 wells logs (Fig 1, Table 1, S1 Fig). Logs are not illustrated in the cross-section due to image-size constraints. Instead, the cross-section exhibits color-coded formational thicknesses within and between adjacent wells. Numbers relate to well locations shown in Fig 1. Numbers in red indicate reference logs shown in detail in Figs 5–8. Note the southward thickening (mostly up-section) of the Oldman Formation and the commensurate thinning of the Dinosaur Park Fm in southeastern-most, as originally hypothesized by Eberth and Hamblin [1]. The Foremost-Oldman formational contact rises slightly to the north due to stratigraphic thinning of the Oldman Fm. Also note the occurrence of a well-developed two-fold stratigraphic division of the Oldman Fm in the southern-most corner of the field area (Twp 01–05). This pattern of a lower sandstone dominated interval overlain by a mudstone dominated interval compares closely to that described by Rogers et al. [9, 14] for the Judith River Formation. The contact between the two intervals in southeast Alberta thus likely marks the mid-Judith discontinuity (MJD) described by those authors.",
    "originalCaption": "Stratigraphic cross-section A–A’.\nCross-section A-A’ is based on data from 35 wells logs (Fig 1, Table 1, S1 Fig). Logs are not illustrated in the cross-section due to image-size constraints. Instead, the cross-section exhibits color-coded formational thicknesses within and between adjacent wells. Numbers relate to well locations shown in Fig 1. Numbers in red indicate reference logs shown in detail in Figs 5–8. Note the southward thickening (mostly up-section) of the Oldman Formation and the commensurate thinning of the Dinosaur Park Fm in southeastern-most, as originally hypothesized by Eberth and Hamblin [1]. The Foremost-Oldman formational contact rises slightly to the north due to stratigraphic thinning of the Oldman Fm. Also note the occurrence of a well-developed two-fold stratigraphic division of the Oldman Fm in the southern-most corner of the field area (Twp 01–05). This pattern of a lower sandstone dominated interval overlain by a mudstone dominated interval compares closely to that described by Rogers et al. [9, 14] for the Judith River Formation. The contact between the two intervals in southeast Alberta thus likely marks the mid-Judith discontinuity (MJD) described by those authors.",
    "shortIntroZh": "顶部剖面路线与底部测井位置对齐，色带表达地层连续性并显示标高。",
    "detailZh": "顶部剖面路线与底部测井位置对齐，色带表达地层连续性并显示标高。 原钻孔、标高、地层厚度和解释不能迁移。图1/2地图曾被审稿要求澄清许可，本案例只采用作者图9剖面，不含地图素材。",
