    "summary": "(a) Inter-individual distance (m) for groups (n = 10 per condition) of five carp (Cyprinus carpio) during experimental trials under ambient and masked conditions; and median inter-individual distance ± median absolute deviation over time during ambient control (AMB-C: solid line) and treatment (dash-dotted line) conditions.(b) ambient low SPL (‘AMB-LOW’); (c) ambient intermediate SPL (‘AMB-INT’); (d) ambient high SPL (‘AMB-HIGH’); (e) masking low SPL (‘MASK-LOW’); (f) masking intermediate SPL (‘MASK-INT’); and (g) masking high SPL (‘MASK-HIGH’). Notes: ‘SPL’ is Sound Pressure Level, while ‘MASK-C’ is the masking control. Raincloud plots show main summary statistics (i.e., boxplot with median, interquartile range, max/min), kernel density estimate (i.e., shaded grey area indicating probability density function of the variable), and raw data (i.e., points). As individual trials consist of repeated measures over time, for each condition in panel ‘a’, raw data points are shown per trial using the viridis colour scale. In panels ‘b’ to ‘g’, vertical green dashed lines (speaker with “waves”) indicate start of the tonal exposure period and vertical purple dashed lines (speaker with an X), the end.",
