      "basis": "2021\nSierksma, Borst\n\nThis is an open access article distributed under the terms of the Creative Commons Attribution License, which permits unrestricted use, distribution, and reproduction in any medium, provided the original author and source are credited.",
      "evidenceFile": "docs/infographic-v400/evidence/papers/pcbi.1009527.xml",
      "captionEvidence": "<fig xmlns:ns0=\"http://www.w3.org/1999/xlink\" id=\"pcbi.1009527.g002\" position=\"float\">\n<object-id pub-id-type=\"doi\">10.1371/journal.pcbi.1009527.g002</object-id>\n<label>Fig 2</label>\n<caption>\n<title>An electrical circuit for the prespike.</title>\n<p>(A) Drawing of the calyx of Held synapse. The calyx of Held terminal (‘pre’) covers a large part of the soma of its target neuron (‘post’). In between is the synaptic cleft (not drawn to scale), a small space where membrane currents will flow during a presynaptic AP. (B) Electrical circuit to reproduce the prespike. Presynaptic membrane currents can leave the synaptic cleft via the cleft conductance (<italic>g</italic><sub>cl</sub>) or through the postsynaptic cell. It is assumed that the conductance from the edge of the cleft to ground is relatively large compared to the cleft conductance itself [<xref ref-type=\"bibr\" rid=\"pcbi.1009527.ref038\">38</xref>,<xref ref-type=\"bibr\" rid=\"pcbi.1009527.ref039\">39</xref>].</p>\n</caption>\n<graphic mimetype=\"image\" position=\"float\" ns0:href=\"info:doi/10.1371/journal.pcbi.1009527.g002\" ns0:type=\"simple\" />\n</fig>\n",
