    "title": "Trade-off between local transmission and long-range dispersal drives infectious disease outbreak size in spatially structured populations",
    "titleZh": "把空间点模式与对应模拟结局分布配对；小提琴叠加原始观测，展示多峰而不只展示均值。",
    "summary": "Distributions of outbreak sizes in clustered populations.\nA) Point pattern characterized by four high density clusters. The point pattern is generated by a random field with variance = 8 and scale = 8 (Supporting Information). B) Distributions of outbreaks sizes stratified by origin of the epidemic obtained by running the model in the point pattern shown in panel A. C) Map of Dutch poultry farms with more than 100 chickens. The point pattern is characterized by two clusters D) Distributions of outbreaks sizes stratified by origin of the epidemic obtained by running the model among the Dutch farms. Hosts in the clusters have individual reproduction number R_{i} >1, while hosts outside the clusters have individual reproduction number R_{i} ≥ 1 (Supporting Information). The spatial SIR model with default kernel has been run as many times as the number of hosts (2000 for panels A and B; 2175 for panels C and D, starting each time in a different host.",
