    "summary": "Identification of intercellular communication in diseased human skin.(A) Dot plot displays the predicted interactions between Inflam. FIB and the specified immune cell types. The color of the points reflects the communication probability, while the size of the points represents the calculated p-value. Blank areas signify a communication probability of zero. (B) Violin plot shows the expression levels of genes IL-13 and THBS2 across samples. (C) Circos plot depicts intercellular communication from Inflam. FIB to other cell types. The arrow points from the ligands in the sending cells to the receptors in the receiving cells. The thickness of the line and the size of the arrow reflect the expression of the ligands and receptors, respectively. (D) Illustration of representative ligands from Inflam. FIB to other cell types.",
