    "title": "Quick tips for creating effective and impactful biological pathways using the Systems Biology Graphical Notation",
    "titleZh": "通过重排、克隆节点与专业符号改善同一细胞周期网络，保留连接语义。",
    "summary": "Example of the Drosophila cell cycle initial SBGN drawing (left) and beautified SBGN network (right).\nWe generated the SBGN map of the following study “Dynamical modeling of syncytial mitotic cycles in Drosophila embryos” by Calzone et al. [16, 17]. First, we created an initial map with the different reactions found in the Drosophila cell cycle. Then we beautified the map by duplicating FZY with clone markers in order to reduce edge crossings, adding colors, and optimising arc positions. The colors categorise the different reactions: green processes represent creation or degradation of entities (“source and sink”) and grey processes show import and export of entities between compartments. The red processes and arcs visualise the positive feedback exerted by the MPF. The purple processes highlight the switch between the activation and the inactivation of MPF. FZY, fizzy; MPF, maturation promoting factor; SBGN, Systems Biology Graphical Notation.",
    "originalCaption": "Example of the Drosophila cell cycle initial SBGN drawing (left) and beautified SBGN network (right).\nWe generated the SBGN map of the following study “Dynamical modeling of syncytial mitotic cycles in Drosophila embryos” by Calzone et al. [16, 17]. First, we created an initial map with the different reactions found in the Drosophila cell cycle. Then we beautified the map by duplicating FZY with clone markers in order to reduce edge crossings, adding colors, and optimising arc positions. The colors categorise the different reactions: green processes represent creation or degradation of entities (“source and sink”) and grey processes show import and export of entities between compartments. The red processes and arcs visualise the positive feedback exerted by the MPF. The purple processes highlight the switch between the activation and the inactivation of MPF. FZY, fizzy; MPF, maturation promoting factor; SBGN, Systems Biology Graphical Notation.",
    "shortIntroZh": "通过重排、克隆节点与专业符号改善同一细胞周期网络，保留连接语义。",
    "detailZh": "通过重排、克隆节点与专业符号改善同一细胞周期网络，保留连接语义。 节点克隆不代表新增物种，布局优化不等于原模型被科学验证。",
