    "originalCaption": "Rearrangement of observations between cluster’s DoLP quartiles.\n(a) HCA clusters. (b) GMM clusters. Left panels show rearrangements between the unpolarized and the DoLP datasets, and right panels illustrate differences between co-polarized and DoLP datasets. Each quartile (Q_{1}—Q_{4}) is labeled with the number of observations. The flows (lines) between quartiles indicate the fraction of observations, with line width proportional to the number of observations. To plot the alluvial diagrams we use RAWGraphs [65].",
