    "titleZh": "观测和期望的负对数 p 值按分位对应，对角线与区间用于观察偏离。",
    "summary": "Quantile-quantile plot for meta-analytic p-values of association between SNPs and TBscore.\nThe quantile-quantile (Q-Q) plot shows the inverse log(10) of the observed p-values on the Y-axis relative to what is expected if there was no association on the x-axis. Deviations above the line indicate an association with the outcome. If the line deviates at the low quantiles, then this is considered evidence to suggest genome-wide inflation of the test statistics, which typically indicates unmeasured confounding (λ = 0.98).",
    "originalCaption": "Quantile-quantile plot for meta-analytic p-values of association between SNPs and TBscore.\nThe quantile-quantile (Q-Q) plot shows the inverse log(10) of the observed p-values on the Y-axis relative to what is expected if there was no association on the x-axis. Deviations above the line indicate an association with the outcome. If the line deviates at the low quantiles, then this is considered evidence to suggest genome-wide inflation of the test statistics, which typically indicates unmeasured confounding (λ = 0.98).",
    "shortIntroZh": "观测和期望的负对数 p 值按分位对应，对角线与区间用于观察偏离。",
