    "title": "Examination of yield, bacteriolytic activity and cold storage of linker deletion mutants based on endolysin S6_ORF93 derived from Staphylococcus giant bacteriophage S6",
    "titleZh": "结构域边界和截短构建沿氨基酸位置排列，与三维结构预测并列。",
    "summary": "Description of ORF93 and its mutants.\nThe domains and linker are colored as follows: CHAP domain in green, linker in red, and SH3 domain in yellow. (A) Schematic diagram of ORF93 based on the primary structure. Each number represents the amino acid position from the N-terminus at both ends of the domain, counted from the N-terminus. (B) Predicted protein structure of ORF93. (C) Schematic diagram of ORF93 mutants based on the primary structure. The linker deletions are shown as shadowed areas. The numbers around shadowed areas represent the amino acid position from the N-terminus at both ends of the deletion area. ORF93-Δ05, ORF93-Δ10, ORF93-Δ15, and ORF93-Δ20 are the ORF93 mutants which 5, 10, 15, and 20 amino acids were deleted in the upstream direction from the 157^{th} amino acid from the N-terminus. The predicted linker lengths are 21, 16, 11, and 6 amino acids, respectively. (D) Predicted protein structures of ORF93-Δ05, ORF93-Δ10 and ORF93-Δ15. These protein structures were overlapped based on the CHAP domain. (E) Predicted protein structure of ORF93-Δ20.",
    "originalCaption": "Description of ORF93 and its mutants.\nThe domains and linker are colored as follows: CHAP domain in green, linker in red, and SH3 domain in yellow. (A) Schematic diagram of ORF93 based on the primary structure. Each number represents the amino acid position from the N-terminus at both ends of the domain, counted from the N-terminus. (B) Predicted protein structure of ORF93. (C) Schematic diagram of ORF93 mutants based on the primary structure. The linker deletions are shown as shadowed areas. The numbers around shadowed areas represent the amino acid position from the N-terminus at both ends of the deletion area. ORF93-Δ05, ORF93-Δ10, ORF93-Δ15, and ORF93-Δ20 are the ORF93 mutants which 5, 10, 15, and 20 amino acids were deleted in the upstream direction from the 157^{th} amino acid from the N-terminus. The predicted linker lengths are 21, 16, 11, and 6 amino acids, respectively. (D) Predicted protein structures of ORF93-Δ05, ORF93-Δ10 and ORF93-Δ15. These protein structures were overlapped based on the CHAP domain. (E) Predicted protein structure of ORF93-Δ20.",
    "shortIntroZh": "结构域边界和截短构建沿氨基酸位置排列，与三维结构预测并列。",
    "detailZh": "结构域边界和截短构建沿氨基酸位置排列，与三维结构预测并列。 结构预测不是实验解析结构；氨基酸坐标不能当核苷酸坐标。",
