    "summary": "Computational workflow of MBTFM.\n(A) Actin and paxillin images are segmented and converted into a whole cell model, with an individual tension value assigned to each stress fiber and one global tension value assigned to the actin networks of the cell. (B) Each set of model parameters leads to an error estimate which is then minimized to estimate the best fit to the experimentally measured displacement field. In contrast to standard traction force microscopy, no regularization scheme is required for MBTFM.",
    "originalCaption": "Computational workflow of MBTFM.\n(A) Actin and paxillin images are segmented and converted into a whole cell model, with an individual tension value assigned to each stress fiber and one global tension value assigned to the actin networks of the cell. (B) Each set of model parameters leads to an error estimate which is then minimized to estimate the best fit to the experimentally measured displacement field. In contrast to standard traction force microscopy, no regularization scheme is required for MBTFM.",
