    "summary": "Kernel density of propensity scores before and after matching.Notes: This figure displays kernel density estimates of propensity scores before and after matching. The sample comprises 2,064 firms from 2007 to 2021. Using k-nearest neighbor matching with a caliper of 0.01, we partitioned firms into treatment and control groups based on characteristics similarity. The blue solid line represents the treatment group; the red dotted line indicates the control group.",
    "originalCaption": "Kernel density of propensity scores before and after matching.Notes: This figure displays kernel density estimates of propensity scores before and after matching. The sample comprises 2,064 firms from 2007 to 2021. Using k-nearest neighbor matching with a caliper of 0.01, we partitioned firms into treatment and control groups based on characteristics similarity. The blue solid line represents the treatment group; the red dotted line indicates the control group.",
