    "titleZh": "底质和生物的可见分类按父子层级展开，多个面板展示局部分支。",
    "summary": "Overview of the coarsest levels of the CATAMI Classification Scheme for (a) physical and (b) biological annotations in imagery; (c) and (d) show details of the ‘bryozoa’ and the ‘echinoderms’ branches.\nThe biological classification at coarsest level is into phyla or broad groups, which are then divided using either taxonomy or morphology (as shown here), depending on what can be more consistently determined from imagery. The number of categories (C) and levels (L) defined under each branch are shown. The full classification scheme can be viewed at http://www.catami.org/classification [53].",
    "originalCaption": "Overview of the coarsest levels of the CATAMI Classification Scheme for (a) physical and (b) biological annotations in imagery; (c) and (d) show details of the ‘bryozoa’ and the ‘echinoderms’ branches.\nThe biological classification at coarsest level is into phyla or broad groups, which are then divided using either taxonomy or morphology (as shown here), depending on what can be more consistently determined from imagery. The number of categories (C) and levels (L) defined under each branch are shown. The full classification scheme can be viewed at http://www.catami.org/classification [53].",
