      "basis": "This is an open access article, free of all copyright, and may be freely reproduced, distributed, transmitted, modified, built upon, or otherwise used by anyone for any lawful purpose. The work is made available under the Creative Commons CC0 public domain dedication.",
      "evidenceFile": "docs/infographic-v400/evidence/papers/pone.0191423.xml",
      "captionEvidence": "<fig xmlns:ns0=\"http://www.w3.org/1999/xlink\" id=\"pone.0191423.g003\" position=\"float\">\n<object-id pub-id-type=\"doi\">10.1371/journal.pone.0191423.g003</object-id>\n<label>Fig 3</label>\n<caption>\n<title>Scaff10 derivatives.</title>\n<p>(A) Overview of the synthesis of Scaff10 derivatives. By addition of iodine in methanol (a), acetophenone derivatives (1) reacted with the corresponding α-iodoketones (2a), removal of excessive iodine by addition of Na<sub>2</sub>SO<sub>3</sub>-solution (b). Resorcinol (3) and diethyl-2-acetylglutarat (4) were transformed into the 7-hydroxycoumarin derivative ethyl 3-(7-hydroxy-4-methyl-2-oxo-chromen-3-yl)propanoate (5a) in ethanolic HCl (c). In the presence of excess potash, 5 reacted with α-haloketone derivatives (2) in a Williamson ether synthesis at 55°C in acetone (d) to 6. Saponification to 7 was carried out in 1 M NaOH at 55–95°C and from 0.3–16 h (e). Final cyclization of ketones to furocoumarin derivatives (8) was carried out upon further heating in NaOH solution (60–110°C) for various times (0.75–10 h) (f). R is indicated in <xref ref-type=\"table\" rid=\"pone.0191423.t001\">Table 1</xref> and (C). (B) Compounds of the generalized structures 6–8 from (A) were allocated into classes 6–8, respectively. (C) Structures of Scaff10 derivatives, which inhibit the AKAP-Lbc/DHPH-RhoA interaction in the homogenous time-resolved fluorescence (HTRF) assay depicted in Fig 3A and B. IC<sub>50</sub> values (μM ± SEM) were obtained from n = 3–15 independent HTRF experiments carried out in duplicate (S3 Table). Structural differences compared to Scaff10-8 are shown in grey. R<sup>2</sup> indicates the coefficient of determination.</p>\n</caption>\n<graphic mimetype=\"image\" position=\"float\" ns0:href=\"info:doi/10.1371/journal.pone.0191423.g003\" ns0:type=\"simple\" />\n</fig>\n",
